package com.exelynt.booking.service; import com.exelynt.booking.dto.*; import com.exelynt.booking.entity.*; import com.exelynt.booking.exception.ApiException; import com.exelynt.booking.repository.*; import com.exelynt.booking.specification.ReservationSpecifications; import org.springframework.data.domain.*; import org.springframework.http.HttpStatus; import org.springframework.security.core.Authentication; import org.springframework.stereotype.Service; import java.math.BigDecimal; import java.util.*;
@Service public class ReservationService {private final ReservationRepository reservations;private final ResourceRepository resources;private final UserRepository users; public ReservationService(ReservationRepository a,ResourceRepository b,UserRepository c){reservations=a;resources=b;users=c;}
 public ReservationResponse create(ReservationRequest r,Authentication a){User u=current(a);validateTimes(r.startTime(),r.endTime());Resource resource=resource(r.resourceId()); if(!resource.isAvailable())throw new ApiException(HttpStatus.CONFLICT,"Resource is unavailable"); Reservation e=new Reservation();e.setUser(u);e.setResource(resource);e.setStartTime(r.startTime());e.setEndTime(r.endTime());e.setStatus(r.status()==null?ReservationStatus.PENDING:r.status());e.setPrice(resource.getPrice());conflict(e,null);return map(reservations.save(e));}
 public PageResponse<ReservationResponse> list(Authentication a,ReservationStatus status,BigDecimal min,BigDecimal max,int page,int size,String sort){if(min!=null&&max!=null&&min.compareTo(max)>0)throw new ApiException(HttpStatus.BAD_REQUEST,"minPrice cannot exceed maxPrice"); if(page<0||size<1||size>100)throw new ApiException(HttpStatus.BAD_REQUEST,"page must be >= 0 and size must be between 1 and 100");String[] parts=sort==null?new String[]{"createdAt","desc"}:sort.split(",");Set<String> allowed=Set.of("price","startTime","endTime","createdAt","status");if(parts.length>2||!allowed.contains(parts[0]))throw new ApiException(HttpStatus.BAD_REQUEST,"Invalid sort field");Sort.Direction d=parts.length==2?Sort.Direction.fromOptionalString(parts[1]).orElseThrow(()->new ApiException(HttpStatus.BAD_REQUEST,"Invalid sort direction")):Sort.Direction.DESC;User owner=isAdmin(a)?null:current(a);return PageResponse.of(reservations.findAll(ReservationSpecifications.filter(owner,status,min,max),PageRequest.of(page,size,Sort.by(d,parts[0]))).map(this::map));}
 public ReservationResponse one(Long id,Authentication a){Reservation r=reservation(id); if(!isAdmin(a)&&!r.getUser().getId().equals(current(a).getId()))throw new ApiException(HttpStatus.FORBIDDEN,"You do not own this reservation");return map(r);} public ReservationResponse update(Long id,ReservationUpdateRequest r){validateTimes(r.startTime(),r.endTime());Reservation e=reservation(id);Resource resource=resource(r.resourceId());e.setResource(resource);e.setStartTime(r.startTime());e.setEndTime(r.endTime());e.setStatus(r.status());e.setPrice(resource.getPrice());conflict(e,id);return map(reservations.save(e));} public void delete(Long id){reservations.delete(reservation(id));}
 private void conflict(Reservation r,Long exclude){if(r.getStatus()!=ReservationStatus.CANCELLED&&reservations.hasConflict(r.getResource().getId(),r.getStartTime(),r.getEndTime(),List.of(ReservationStatus.PENDING,ReservationStatus.CONFIRMED),exclude))throw new ApiException(HttpStatus.CONFLICT,"Resource already has an active overlapping reservation");} private User current(Authentication a){return users.findByUsername(a.getName()).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"Authenticated user not found"));} private boolean isAdmin(Authentication a){return a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ADMIN"));} private Resource resource(Long id){return resources.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Resource not found"));} private Reservation reservation(Long id){return reservations.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Reservation not found"));} private void validateTimes(java.time.LocalDateTime s,java.time.LocalDateTime e){if(!e.isAfter(s))throw new ApiException(HttpStatus.BAD_REQUEST,"endTime must be after startTime");} private ReservationResponse map(Reservation e){return new ReservationResponse(e.getId(),e.getResource().getId(),e.getResource().getName(),e.getUser().getId(),e.getUser().getUsername(),e.getStartTime(),e.getEndTime(),e.getPrice(),e.getStatus());}}
